function [b] = kpi_ecss_block(tj, t0, delta)
%KPI_ECSS_BLOCK  The block of a sample at time tj [s]: the whole number of windows of delta [s] from the window's start t0 [s] (a
%   nanosecond's tolerance, so a sample on a block's edge opens it).
%   tj: real[1] (passed a plain number)
%   t0: real[1] (passed a plain number)
%   delta: real[1] (passed a plain number)
%   returns b: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b = 0;
    b = fix(floor((((tj - t0) / delta) + 1e-9)));
end
